/**
 * Regenerate the frontend contract types from the committed OpenAPI snapshot.
 *
 * The snapshot in `contracts/openapi.v1.json` is the single source of truth.
 * This script never edits the snapshot; it only translates it into the
 * TypeScript types the frontend imports.
 *
 * Usage:
 *   node scripts/generate-api-types.mjs           # write the generated file
 *   node scripts/generate-api-types.mjs --check   # fail when it is out of date
 */
import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(scriptDirectory, "..");
const snapshotPath = resolve(projectRoot, "..", "contracts", "openapi.v1.json");
const outputPath = resolve(projectRoot, "src", "lib", "contracts", "generated.ts");

const HTTP_METHODS = ["get", "post", "put", "patch", "delete"];

const openapi = JSON.parse(await readFile(snapshotPath, "utf8"));

const operations = [];
for (const [path, pathItem] of Object.entries(openapi.paths ?? {})) {
  for (const method of HTTP_METHODS) {
    const operation = pathItem[method];
    if (operation === undefined) {
      continue;
    }
    operations.push({
      method,
      path,
      operationId: operation.operationId ?? `${method}_${path}`,
      summary: operation.summary ?? null,
      description: operation.description ?? null,
    });
  }
}

const schemas = openapi.components?.schemas ?? {};

const lines = [
  "// This file is generated by scripts/generate-api-types.mjs from",
  "// contracts/openapi.v1.json. Do not edit it by hand.",
  "",
  `export const API_TITLE = ${JSON.stringify(openapi.info?.title ?? "Trendsmapp API")};`,
  `export const API_VERSION = ${JSON.stringify(openapi.info?.version ?? "0.0.0")};`,
  "",
  "export type ApiHttpMethod =",
  ...HTTP_METHODS.map((method) => `  | "${method}"`),
  ";",
  "",
  "export interface ApiOperation {",
  "  readonly method: ApiHttpMethod;",
  "  readonly path: string;",
  "  readonly operationId: string;",
  "  readonly summary: string | null;",
  "  readonly description: string | null;",
  "}",
  "",
  "export const API_OPERATIONS: readonly ApiOperation[] = [",
  ...operations.map(
    (operation) =>
      `  {\n` +
      `    method: ${JSON.stringify(operation.method)},\n` +
      `    path: ${JSON.stringify(operation.path)},\n` +
      `    operationId: ${JSON.stringify(operation.operationId)},\n` +
      `    summary: ${JSON.stringify(operation.summary)},\n` +
      `    description: ${JSON.stringify(operation.description)},\n` +
      `  },`,
  ),
  "];",
  "",
];

for (const [name, schema] of Object.entries(schemas)) {
  lines.push(
    `export type ${toTypeName(name)} = ${toTypeScript(schema)};`,
    "",
  );
}

const generated = lines.join("\n");

if (process.argv.includes("--check")) {
  const current = await readFile(outputPath, "utf8").catch(() => "");
  if (current !== generated) {
    console.error(
      `generate-api-types: ${outputPath} is out of date. Run 'pnpm run generate:api-types'.`,
    );
    process.exitCode = 1;
  } else {
    console.log(`generate-api-types: ${outputPath} is current`);
  }
} else {
  await writeFile(outputPath, generated, "utf8");
  console.log(`generate-api-types: wrote ${outputPath}`);
}

function toTypeName(name) {
  return name
    .split(/[^A-Za-z0-9]+/)
    .filter((part) => part.length > 0)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("");
}

function toTypeScript(schema) {
  if (schema === null || schema === undefined) {
    return "unknown";
  }
  if (Array.isArray(schema.enum) && schema.enum.length > 0) {
    return schema.enum.map((value) => JSON.stringify(value)).join(" | ");
  }
  if (Array.isArray(schema.anyOf)) {
    return schema.anyOf.map(toTypeScript).join(" | ");
  }
  if (schema.type === "string") {
    return "string";
  }
  if (schema.type === "number" || schema.type === "integer") {
    return "number";
  }
  if (schema.type === "boolean") {
    return "boolean";
  }
  if (schema.type === "array") {
    return `readonly ${toTypeScript(schema.items)}[]`;
  }
  if (schema.type === "object" || schema.properties !== undefined) {
    const properties = Object.entries(schema.properties ?? {});
    if (properties.length === 0) {
      return "Record<string, unknown>";
    }
    const fields = properties.map(([name, property]) => {
      const optional = schema.required?.includes(name) === true ? "" : "?";
      return `  ${JSON.stringify(name)}${optional}: ${toTypeScript(property)};`;
    });
    return `{\n${fields.join("\n")}\n}`;
  }
  return "unknown";
}
